import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const p=JSON.parse('{"title":"44、【姤】 巽下乾上","description":"温公易说 - 44、【姤】 巽下乾上","frontmatter":{"title":"44、【姤】 巽下乾上","description":"温公易说 - 44、【姤】 巽下乾上"},"headers":[],"relativePath":"zh/classics/wengong/045.md","filePath":"zh/classics/wengong/045.md"}'),n={name:"zh/classics/wengong/045.md"};function l(t,a,s,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_44、【姤】-巽下乾上" tabindex="-1">44、【姤】 巽下乾上 <a class="header-anchor" href="#_44、【姤】-巽下乾上" aria-label="Permalink to “44、【姤】 巽下乾上”">​</a></h1><h3 id="彖曰-姤-遇也。柔遇刚也。勿用取女-不可与长也。天地相遇-品物咸章也。刚遇中正-天下大行也。姤之时义-大矣哉。" tabindex="-1">彖曰：姤，遇也。柔遇刚也。勿用取女，不可与长也。天地相遇，品物咸章也。刚遇中正，天下大行也。姤之时义，大矣哉。 <a class="header-anchor" href="#彖曰-姤-遇也。柔遇刚也。勿用取女-不可与长也。天地相遇-品物咸章也。刚遇中正-天下大行也。姤之时义-大矣哉。" aria-label="Permalink to “彖曰：姤，遇也。柔遇刚也。勿用取女，不可与长也。天地相遇，品物咸章也。刚遇中正，天下大行也。姤之时义，大矣哉。”">​</a></h3><p>刚阳德也，君子所尚也。然刚而不中则亢，刚而不正则戾。亢则人疾之，戾则人违之。故刚遇中正，然后可以大行于天下也。姤之时义，大矣哉。姤，消卦也。孔子何大焉？夫世之治乱，人之穷通，事之成败，不可以力致也，不可以数求也，遇与不遇而已矣。舜遇尧而五典克从，百揆时叙。禹稷契皋陶遇舜而六府三事允治，地平天成。伊尹遇汤而格于皇天。师尚父遇文武而天下大定。不然泯泯于众人之中，后世谁克知之？以是观之，姤之为义岂不大哉。</p><h3 id="象曰-天下有风-姤。后以施命诰四方。" tabindex="-1">象曰：天下有风，姤。后以施命诰四方。 <a class="header-anchor" href="#象曰-天下有风-姤。后以施命诰四方。" aria-label="Permalink to “象曰：天下有风，姤。后以施命诰四方。”">​</a></h3><h3 id="初六-系于金柅-贞吉。有攸往-见凶。羸豕孚蹢躅-象曰-系于金柅-柔道牵也。" tabindex="-1">初六：系于金柅，贞吉。有攸往，见凶。羸豕孚蹢躅 象曰：系于金柅，柔道牵也。 <a class="header-anchor" href="#初六-系于金柅-贞吉。有攸往-见凶。羸豕孚蹢躅-象曰-系于金柅-柔道牵也。" aria-label="Permalink to “初六：系于金柅，贞吉。有攸往，见凶。羸豕孚蹢躅 象曰：系于金柅，柔道牵也。”">​</a></h3><h3 id="九二-包有鱼-无咎。不利宾-象曰-包有鱼-义不及宾也。" tabindex="-1">九二：包有鱼，无咎。不利宾 象曰：包有鱼，义不及宾也。 <a class="header-anchor" href="#九二-包有鱼-无咎。不利宾-象曰-包有鱼-义不及宾也。" aria-label="Permalink to “九二：包有鱼，无咎。不利宾 象曰：包有鱼，义不及宾也。”">​</a></h3><h3 id="九三-臀无肤-其行次且。厉无大咎-象曰-其行次且-行未牵也。" tabindex="-1">九三：臀无肤，其行次且。厉无大咎 象曰：其行次且，行未牵也。 <a class="header-anchor" href="#九三-臀无肤-其行次且。厉无大咎-象曰-其行次且-行未牵也。" aria-label="Permalink to “九三：臀无肤，其行次且。厉无大咎 象曰：其行次且，行未牵也。”">​</a></h3><h3 id="九四-包无鱼-起凶-象曰-无鱼之凶-远民也。" tabindex="-1">九四：包无鱼，起凶 象曰：无鱼之凶，远民也。 <a class="header-anchor" href="#九四-包无鱼-起凶-象曰-无鱼之凶-远民也。" aria-label="Permalink to “九四：包无鱼，起凶 象曰：无鱼之凶，远民也。”">​</a></h3><p>姤九四包无鱼起凶，鲁昭公将去季氏，宋乐祁讥之曰：政在季氏三世矣，鲁君丧政四公矣。无民而能逞其志者，未之有也。国君以是镇抚其民，鲁君失民矣。靖以待命，犹可动必忧已。而昭公伐季氏，果不胜而出死于外。</p><h3 id="九五-以杞包瓜-含章-有陨自天-象曰-九五含章-中正也。有陨自天-志不舍命也。" tabindex="-1">九五：以杞包瓜，含章，有陨自天 象曰：九五含章，中正也。有陨自天，志不舍命也。 <a class="header-anchor" href="#九五-以杞包瓜-含章-有陨自天-象曰-九五含章-中正也。有陨自天-志不舍命也。" aria-label="Permalink to “九五：以杞包瓜，含章，有陨自天 象曰：九五含章，中正也。有陨自天，志不舍命也。”">​</a></h3><p>杞材之美者也，包瓜不食之物也。</p><h3 id="上九-姤其角-吝无咎-象曰-姤其角上穷-吝也。" tabindex="-1">上九：姤其角，吝无咎 象曰：姤其角上穷，吝也。 <a class="header-anchor" href="#上九-姤其角-吝无咎-象曰-姤其角上穷-吝也。" aria-label="Permalink to “上九：姤其角，吝无咎 象曰：姤其角上穷，吝也。”">​</a></h3><p>姤其角者，行无所之之谓也。</p>',13)])])}const b=e(n,[["render",l]]);export{p as __pageData,b as default};
